begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
select public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select public.ai_account('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
update public.ai_credit_accounts set revenuecat_id='11111111-1111-4111-8111-111111111111' where user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
update public.ai_credit_accounts set revenuecat_id='22222222-2222-4222-8222-222222222222' where user_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
select ok(not has_function_privilege('authenticated','public.ai_apply_credit_purchase(uuid[],text,boolean)','EXECUTE'),'clients cannot fulfill purchases');
select ok(not has_table_privilege('authenticated','public.ai_credit_purchases','SELECT'),'purchase fingerprints are server-only');
select is(public.ai_apply_credit_purchase(array['11111111-1111-4111-8111-111111111111']::uuid[],repeat('a',64),false)->>'status','credited','purchase fulfills');
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,115,'pack adds 100');
select is(public.ai_apply_credit_purchase(array['11111111-1111-4111-8111-111111111111']::uuid[],repeat('a',64),false)->>'status','credited','duplicate acknowledges');
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,115,'duplicate never credits twice');
select public.ai_apply_credit_purchase(array['22222222-2222-4222-8222-222222222222']::uuid[],repeat('a',64),false);
select is((public.ai_account('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')->>'balance')::integer,15,'transfer never credits another wallet');
select is(public.ai_credit_purchase_status('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64))->>'creditPurchaseStatus','credited','owner can confirm');
select is(public.ai_credit_purchase_status('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('a',64))->>'creditPurchaseStatus','pending','another account cannot inspect a receipt');
select public.ai_apply_credit_purchase(array['11111111-1111-4111-8111-111111111111']::uuid[],repeat('b',64),false);
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,215,'second pack grants again');
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'creditPackCount')::integer,2,'wallet can recover packs without a client order ID');
select public.ai_apply_credit_purchase(array['22222222-2222-4222-8222-222222222222']::uuid[],repeat('a',64),true);
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,115,'refund debits the original owner');
select public.ai_apply_credit_purchase('{}',repeat('a',64),true);
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,115,'repeated refund never debits twice');
select public.ai_apply_credit_purchase(array['11111111-1111-4111-8111-111111111111']::uuid[],repeat('a',64),false);
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,115,'delayed grant cannot undo refund');
select public.ai_apply_credit_purchase('{}',repeat('c',64),true);
select public.ai_apply_credit_purchase(array['11111111-1111-4111-8111-111111111111']::uuid[],repeat('c',64),false);
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,115,'refund received before purchase blocks fulfillment');
update public.ai_credit_accounts set balance=3 where user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
select public.ai_apply_credit_purchase('{}',repeat('b',64),true);
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,0,'refund balance stops at zero');
select is((select amount from public.ai_credit_ledger where kind='purchase_refund' order by id desc limit 1),-3,'ledger records actual debit');
select is(public.ai_apply_credit_purchase('{}',repeat('d',64),false)->>'status','unmapped','unmapped purchase is retried');
select is((select count(*)::integer from public.ai_credit_purchases where purchase_hash=repeat('d',64)),0,'unmapped purchase is not claimed');
select is(public.ai_apply_credit_purchase(array['33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222']::uuid[],repeat('d',64),false)->>'status','unmapped','ambiguous aliases cannot pick a wallet');
select public.ai_apply_credit_purchase(array['22222222-2222-4222-8222-222222222222','11111111-1111-4111-8111-111111111111']::uuid[],repeat('d',64),false);
select is((public.ai_account('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb')->>'balance')::integer,115,'current identity takes precedence over aliases');
delete from auth.users where id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
select ok((select user_id is null from public.ai_credit_purchases where purchase_hash=repeat('d',64)),'deletion unlinks the fingerprint');
select public.ai_apply_credit_purchase(array['11111111-1111-4111-8111-111111111111']::uuid[],repeat('d',64),false);
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,0,'deleted account purchase cannot be granted again');
select is(public.ai_apply_credit_purchase('{}',repeat('d',64),true)->>'status','refunded','refund after deletion is acknowledged');
select is((select count(*)::integer from public.ai_credit_ledger where kind='purchase'),2,'ledger records exactly one entry per surviving purchase');
select * from finish();
rollback;
